// 传入，processing/publishing 两个阶段复用同一条 SQL。0 行受影响 = 这个
// worker 已经被 reconciliation 判定卡死并取代（version 或 status 已经不
// 匹配），调用方必须立刻停手，不能再写 chunks 或发布。
func (q *Queries) RenewDocumentLease(ctx context.Context, arg RenewDocumentLeaseParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, renewDocumentLease,
		arg.LeaseExpiresAt,
		arg.ID,
		arg.Version,
		arg.Status,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
